    mutationFn: (v: { id: number; to: number }) => reassignClaim(sheetId, user, v.id, v.to),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const moveTo = (id: number) => {
    const to = Number(targets[id] ?? others[0]?.id ?? NaN);
    actOnce(() => {
      move.reset();
