  };

  const act = (id: number, action: ClaimAction) => {
    actOnce(() => {
      move.reset();
      reassign.reset();
      deferral.reset();
      redating.reset();
      proof.reset();
      division.reset();
      setEditRefused(null);
      locking.reset();
      return move.mutateAsync({ id, action });
    });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    move.reset();
    reassign.reset();
    deferral.reset();
    redating.reset();
    proof.reset();
    division.reset();
    locking.reset();
    if (c.status !== 'DRAFT') {
      setEditRefused({ id: c.id, message: `A ${c.status} claim cannot be edited. To change it, void it and add a new one.` });
      return;
    }
