      setEditRefused({ id: c.id, message: `${c.lockedBy} is editing this claim; it cannot be edited until they save or cancel.` });
      return;
    }
    setEditRefused(null);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' });
    setEditing(c.id);
    save.reset();
    locking.mutate(c.id);
  };

  const cancel = () => {
    const id = editing;
    setForm(EMPTY);
